---游戏内充值接口
---@param type number 充值类型
---@param productIdList table 商品id[]
function ClientHelper.onGameRecharge(rechargeType, productIdList, orderBody)
    if not productIdList then
        return
    end
    local params = json.encode(productIdList)
    local body = ""
    if orderBody then
        body = json.encode(orderBody)
    end
    HostApi.onGameRecharge(rechargeType, params, body)
end

---设置bool变量到app缓存
---@param key string 变量唯一标识
---@param value boolean 变量值
function ClientHelper.putBoolForKey(key, value)
    if Platform.isWindow() then
        SharePreferences:putBoolForKey(key, value)
    else
        HostApi.putBoolForKey(key, value)
    end
end

---获取app缓存bool变量
---@param key string 变量唯一标识
---@param default boolean 变量默认值
---@return boolean 变量值
function ClientHelper.getBoolForKey(key, default)
    if Platform.isWindow() then
        return SharePreferences:getBoolForKey(key, default)
    else
        return HostApi.getBoolForKey(key, default)
    end
end

